// File: mod/digitaleval/amd/src/gradingpanel.js
define(['core/modal_factory', 'core/modal_events', 'core/ajax', 'core/str'],
function(ModalFactory, ModalEvents, Ajax, Str) {

    const SELECTORS = {
        button: '#start-grading-button'
    };

    /**
     * Initialize grading panel.
     */
    const init = () => {
        const button = document.querySelector(SELECTORS.button);
        if (!button) {
            // console.warn('No grading button found.');
            return;
        }

        button.addEventListener('click', async () => {
            const cmid = button.dataset.cmid;

            // Create modal shell
            const modal = await ModalFactory.create({
                type: ModalFactory.types.DEFAULT,
                title: await Str.get_string('grading', 'mod_digitaleval'),
                body: '<div id="grading-modal-body">Loading submission...</div>',
                large: true
            });

            modal.show();

            // Load the first grading page via AJAX
            Ajax.call([{
                methodname: 'mod_digitaleval_get_next_submission',
                args: { cmid: cmid }
            }])[0]
            .then(html => {
                document.getElementById('grading-modal-body').innerHTML = html;
            })
            .catch(() => {
                document.getElementById('grading-modal-body').innerHTML = '<p>Error loading submission.</p>';
            });
        });
    };

    return { init: init };
});